import java.util.*;
import java.lang.*;
import java.io.*;
//team BST Dominators
class Codechef {
    static long []sum;
    static int n;
    
    static long calculate(int A,int B){
        int x=A;
        int y=A+2*B;
        int z = 3*n-2*A-B;
        
        return 2l * sum[x] + sum[y]+3l*sum[z];
        
    }
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
       int t = sc.nextInt();
       while(t-->0){
           n = sc.nextInt();
           int total = 3*n;
           long[] a = new long [total];
            for (int i = 0 ; i < total ;i++ ){
                a[i] = sc.nextLong();
            } 
            Arrays.sort(a);
            sum = new long[total+1];
             for (int i = 1; i <= total ; i++){
                 sum[i]= sum[i-1]+a [total-i];
             }
             long answer = 0 ;
             for(int A = 0; A <= n ; A++){
                 int left = 0 ;
                 int right = n - A ;
                 while(left <right){
                     
                         int mid = (left + right)/2;
                         long x = calculate(A , mid );
                         long y = calculate(A , mid +1);
                         if (y>x){
                             left = mid+1;
                         } else{
                             right = mid;
                             
                         }
                     }
                     long current = calculate (A, left);
                     if (current > answer){
                         answer = current;
                     }
                 }
                 System.out.println(answer);
             }
             sc.close();
       }
       
    }
